/* client */
int fd = socket(AF_INET, SOCK_STREAM, 0);
struct sockaddr_in a = {.sin_family = AF_INET, .sin_port = htons(443)};
inet_pton(AF_INET, "203.0.113.7", &a.sin_addr);
if (connect(fd, (struct sockaddr *)&a, sizeof a) < 0)
    perror("connect");          /* ETIMEDOUT, ECONNREFUSED, ... */

/* server */
int ls = socket(AF_INET, SOCK_STREAM, 0);
bind(ls, (struct sockaddr *)&addr, sizeof addr);
listen(ls, 128);                /* kernel now answers SYNs */
int c = accept(ls, NULL, NULL); /* returns after the 3rd packet */
